"""Local review of model previews and source-linked dimensions, no source copies."""
from pathlib import Path
import json,html
ROOT=Path(__file__).resolve().parents[1];dest=ROOT/'recon/v57'
sections=[('Your house','house_front'),('Porch detail','house_porch'),('Holmdale from above','holmdale_overhead'),('Holmdale end','holmdale'),('Station junction shops','junction_shops'),('Victorian retail terrace','retail_terrace'),('Hall and cafe vicinity','hall_cafe'),('Supermarket frontage','supermarket'),('Barkby joining street','barkby')]
parts=['<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Syston surveyed route v57</title><style>body{background:#13191d;color:#eef2ed;font:17px system-ui;margin:0 auto;padding:24px;max-width:1400px}h1{font-size:32px}p{max-width:1000px;line-height:1.5}a{color:#a7d9ff}img{width:100%;border-radius:7px}section{margin:32px 0}figure{margin:0}details{background:#202a30;padding:12px}table{border-collapse:collapse;width:100%;font-size:14px}td,th{padding:8px;text-align:left;border-bottom:1px solid #43505a}.notice{border-left:4px solid #e9b269;padding-left:16px}</style><h1>Holmdale → Melton → Barkby · v57</h1><p>368 accepted Street View views across the selected 1.09 km route; detailed notes and 60 new frontage assemblies. Material previews below are Blender renders. The approved porch and perpendicular garage are retained.</p><p class="notice">This is a Blender working copy. Heights, concealed footprints and frontage positions remain approximate. Holmdale’s end uses a saved overhead trace. A short Barkby join deviates by up to 20.25 m to preserve older approved buildings. Walls and the closure beyond B are game adaptations. BO3 is unchanged.</p><p><a href="../../references/streetview-capture/authored-route-2026-10-11/index.html">Local source photo browser</a> · <a href="../../docs/SURVEYED_ROUTE_V57.md">Checkpoint notes</a> · <a href="../../assets/blender/pharmacie-surveyed-route-v57.blend">Latest editable Blender file</a></p>']
for title,name in sections:
 parts.append(f'<section><h2>{html.escape(title)}</h2><figure><img loading="lazy" src="{name}_after.png" alt="{html.escape(title)} latest Blender preview"></figure>')
 before=ROOT/'recon/v54'/f'{name}_before.png'
 if before.exists():parts.append(f'<details><summary>Before this street pass, matched camera</summary><img loading="lazy" src="../v54/{name}_before.png" alt="Before street pass"></details>')
 parts.append('</section>')
schedule=json.loads((ROOT/'recon/v54/prepared-street.json').read_text())['frontages'];parts.append('<h2>Frontage schedule</h2><p>Dimensions are estimates in physical metres; the retained model frame uses 1.06406865 Blender units per metre. Chainage is along the authored route. R001–R009 side placement was corrected in v57; the v57 model and correction manifest take precedence over the trial schedule.</p><table><tr><th>ID</th><th>Feature</th><th>Route m</th><th>Width / depth / eaves m</th><th>Source stops</th></tr>')
for r in schedule:parts.append(f'<tr><td>{r["id"]}</td><td>{html.escape(r["label"])}</td><td>{r["chain_m"]:.1f}</td><td>{r["width_m"]} / {r["depth_m"]} / {r["eaves_m"]}</td><td>{html.escape(str(r["source_stops"]))}</td></tr>')
parts.append('</table></html>');(dest/'index.html').write_text(''.join(parts),encoding='utf-8');print(dest/'index.html')
